    public function __construct(private readonly PDO$pdo){}

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function createComplianceItem(string$o,string$u,string$p,array$input):array
    {
        $this->assertProject($o,$u,$p);$this->confirmed($input);$subjectType=$this->choice($input['subjectType']??null,['professional','company','contractor','supplier'],'trust_subject_type_invalid');$subjectName=$this->text($input['subjectName']??null,220,'trust_subject_name_required');$category=$this->choice($input['category']??null,['professional_registration','company_document','insurance','contractor_supplier'],'trust_category_invalid');$this->assertSubjectCategory($subjectType,$category);$documentType=$this->text($input['documentType']??null,100,'trust_document_type_required');$authority=$this->text($input['authority']??null,160,'trust_authority_required');$reference=$this->text($input['referenceNumber']??null,180,'trust_reference_required');$this->assertDocumentType($category,$documentType,$authority);$grade=$this->choice($input['grade']??null,['self_declared','document_uploaded'],'trust_grade_invalid');$file=$this->nullableId($input['evidenceFileId']??null,'trust_evidence_file_invalid');if($grade==='document_uploaded'&&$file===null)throw new TrustException('trust_document_evidence_required');if($file!==null)$this->assertEvidence($o,$p,$file);$details=$this->object($input['details']??[],'trust_details_invalid');$expires=$this->nullableDate($input['expiresOn']??null,'trust_expiry_invalid');$coverage=$this->nullableInteger($input['coverageAmountCents']??null,'trust_coverage_invalid');$required=$this->nullableInteger($input['requiredCoverageCents']??null,'trust_required_coverage_invalid');if($category==='insurance'&&($coverage===null||$required===null||$required===0))throw new TrustException('trust_insurance_threshold_required');$purpose=$this->text($input['purpose']??null,500,'trust_processing_purpose_required');$retention=$this->date($input['retentionUntil']??null,'trust_retention_invalid');if(($input['consentGiven']??false)!==true)throw new TrustException('trust_consent_required');if($retention<(new DateTimeImmutable('today'))->format('Y-m-d'))throw new TrustException('trust_retention_invalid');$status=$this->effectiveStatus($expires,$coverage,$required,$grade);$id=Identifier::generate();
        return$this->transaction(function()use($o,$u,$p,$subjectType,$subjectName,$category,$documentType,$authority,$reference,$grade,$file,$details,$expires,$coverage,$required,$purpose,$retention,$status,$id):array{$this->pdo->prepare('INSERT INTO trust_compliance_items(id,organisation_id,project_id,subject_type,subject_name,category,document_type,authority,reference_number,grade,evidence_file_id,coverage_amount_cents,required_coverage_cents,details,expires_on,status,popia_consent_at,processing_purpose,retention_until,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:subject_type,:subject_name,:category,:document_type,:authority,:reference,:grade,UNHEX(:file),:coverage,:required,:details,:expires,:status,UTC_TIMESTAMP(6),:purpose,:retention,UNHEX(:u))')->execute(['id'=>$id,'o'=>$o,'p'=>$p,'subject_type'=>$subjectType,'subject_name'=>$subjectName,'category'=>$category,'document_type'=>$documentType,'authority'=>$authority,'reference'=>$reference,'grade'=>$grade,'file'=>$file,'coverage'=>$coverage,'required'=>$required,'details'=>$this->json($details),'expires'=>$expires,'status'=>$status,'purpose'=>$purpose,'retention'=>$retention,'u'=>$u]);$payload=['complianceItemId'=>$id,'subjectType'=>$subjectType,'category'=>$category,'documentType'=>$documentType,'authority'=>$authority,'referenceNumber'=>$reference,'grade'=>$grade,'status'=>$status,'expiresOn'=>$expires,'coverageAmountCents'=>$coverage,'requiredCoverageCents'=>$required,'externalVerificationClaimed'=>false];$this->record($o,$p,$u,'trust_compliance_item',$subjectName,$status,$payload,[$id,...($file?[$file]:[])]);$this->audit($o,$u,'trust.compliance_item_created','trust_compliance_item',$id,$payload);if(in_array($status,['expired','coverage_gap'],true))$this->risk($o,$p,'trust_compliance_item',$id,$status==='coverage_gap'?'Coverage gap':'Expired compliance evidence',$status==='coverage_gap'?'Recorded coverage is below the project requirement.':'Recorded compliance evidence is expired.','high',true);return$this->item($o,$p,$id);});
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function reviewComplianceItem(string$o,string$reviewer,string$id,array$input):array
    {
        $this->confirmed($input);$this->governor($o,$reviewer);$decision=$this->choice($input['decision']??null,['manually_reviewed','externally_verified','rejected'],'trust_review_decision_invalid');$note=$this->text($input['note']??null,4000,'trust_review_note_required');$provider=$this->nullableText($input['provider']??null,160,'trust_provider_invalid');$providerReference=$this->nullableText($input['providerReference']??null,180,'trust_provider_reference_invalid');if($decision==='externally_verified'&&($provider===null||$providerReference===null))throw new TrustException('external_provider_evidence_required');$row=$this->scopedItem($o,$id);if($row['created_by']===$reviewer)throw new TrustException('trust_self_review_forbidden');$status=$this->effectiveStatus($row['expires_on'],isset($row['coverage_amount_cents'])?(int)$row['coverage_amount_cents']:null,isset($row['required_coverage_cents'])?(int)$row['required_coverage_cents']:null,$decision);
        $this->pdo->beginTransaction();try{$this->pdo->prepare('UPDATE trust_compliance_items SET grade=:decision,status=:status,provider=:provider,provider_reference=:provider_reference,reviewed_by=UNHEX(:reviewer),reviewed_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)')->execute(['decision'=>$decision,'status'=>$status,'provider'=>$provider,'provider_reference'=>$providerReference,'reviewer'=>$reviewer,'id'=>$id,'o'=>$o]);$this->pdo->prepare('INSERT INTO trust_compliance_reviews(id,organisation_id,compliance_item_id,reviewer_user_id,decision,review_note,provider,provider_reference) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:item),UNHEX(:reviewer),:decision,:note,:provider,:provider_reference)')->execute(['id'=>Identifier::generate(),'o'=>$o,'item'=>$id,'reviewer'=>$reviewer,'decision'=>$decision,'note'=>$note,'provider'=>$provider,'provider_reference'=>$providerReference]);$payload=['complianceItemId'=>$id,'decision'=>$decision,'status'=>$status,'provider'=>$provider,'providerReference'=>$providerReference,'externalVerificationClaimed'=>$decision==='externally_verified'];$this->record($o,$row['project_id'],$reviewer,'trust_compliance_review',$row['subject_name'].' review',$status,$payload,[$id]);$this->audit($o,$reviewer,'trust.compliance_item_reviewed','trust_compliance_item',$id,$payload);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$this->item($o,$row['project_id'],$id);
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function createProcessingActivity(string$o,string$u,string$p,array$input):array
    {
        $this->assertProject($o,$u,$p);$this->confirmed($input);$name=$this->text($input['activityName']??null,220,'popia_activity_name_required');$purpose=$this->text($input['purpose']??null,500,'popia_purpose_required');$basis=$this->choice($input['lawfulBasis']??null,['consent','contract','legal_obligation','legitimate_interest','public_law_duty'],'popia_lawful_basis_invalid');$subjects=$this->strings($input['dataSubjects']??null,30,'popia_data_subjects_invalid');$categories=$this->strings($input['dataCategories']??null,30,'popia_data_categories_invalid');$recipients=$this->strings($input['recipients']??null,30,'popia_recipients_invalid');$safeguards=$this->text($input['safeguards']??null,2000,'popia_safeguards_required');$retention=$this->date($input['retentionUntil']??null,'popia_retention_invalid');$owner=$this->id($input['ownerUserId']??null,'popia_owner_invalid');$this->assertMember($o,$owner);$status=$retention<(new DateTimeImmutable('today'))->format('Y-m-d')?'review_due':'active';$id=Identifier::generate();return$this->transaction(function()use($o,$u,$p,$name,$purpose,$basis,$subjects,$categories,$recipients,$safeguards,$retention,$owner,$status,$id):array{$this->pdo->prepare('INSERT INTO popia_processing_activities(id,organisation_id,project_id,activity_name,purpose,lawful_basis,data_subjects,data_categories,recipients,safeguards,retention_until,owner_user_id,status,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:name,:purpose,:basis,:subjects,:categories,:recipients,:safeguards,:retention,UNHEX(:owner),:status,UNHEX(:u))')->execute(['id'=>$id,'o'=>$o,'p'=>$p,'name'=>$name,'purpose'=>$purpose,'basis'=>$basis,'subjects'=>$this->json($subjects),'categories'=>$this->json($categories),'recipients'=>$this->json($recipients),'safeguards'=>$safeguards,'retention'=>$retention,'owner'=>$owner,'status'=>$status,'u'=>$u]);$payload=['processingActivityId'=>$id,'lawfulBasis'=>$basis,'retentionUntil'=>$retention,'ownerUserId'=>$owner,'status'=>$status];$this->record($o,$p,$u,'popia_processing_activity',$name,$status,$payload,[$id]);$this->audit($o,$u,'popia.processing_activity_created','popia_processing_activity',$id,$payload);if($status==='review_due')$this->risk($o,$p,'popia_processing_activity',$id,'Processing activity retention review','The recorded retention date has passed.','high',true);return$this->one('popia_processing_activities',$o,$p,$id,['data_subjects','data_categories','recipients']);});
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function createDataSubjectRequest(string$o,string$u,string$p,array$input):array
    {
        $this->assertProject($o,$u,$p);$this->confirmed($input);$type=$this->choice($input['requestType']??null,['access','correction','deletion','objection','portability'],'popia_request_type_invalid');$reference=$this->text($input['requesterReference']??null,180,'popia_request_reference_required');$received=$this->date($input['receivedOn']??null,'popia_request_received_invalid');$due=$this->date($input['dueOn']??null,'popia_request_due_invalid');if($due<$received)throw new TrustException('popia_request_dates_invalid');$scope=$this->text($input['scope']??null,2000,'popia_request_scope_required');$id=Identifier::generate();return$this->transaction(function()use($o,$u,$p,$type,$reference,$received,$due,$scope,$id):array{$this->pdo->prepare("INSERT INTO popia_data_subject_requests(id,organisation_id,project_id,request_type,requester_reference,received_on,due_on,scope,status,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:type,:reference,:received,:due,:scope,'received',UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'p'=>$p,'type'=>$type,'reference'=>$reference,'received'=>$received,'due'=>$due,'scope'=>$scope,'u'=>$u]);$payload=['dataSubjectRequestId'=>$id,'requestType'=>$type,'requesterReference'=>$reference,'dueOn'=>$due];$this->record($o,$p,$u,'popia_data_subject_request','Data-subject request '.$reference,'received',$payload,[$id]);$this->inbox($o,$p,'popia.data_subject_request_received','POPIA data-subject request received','Track the verified request and response deadline.','high',$payload);$this->audit($o,$u,'popia.data_subject_request_created','popia_data_subject_request',$id,$payload);return$this->one('popia_data_subject_requests',$o,$p,$id,[]);});
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function transitionDataSubjectRequest(string$o,string$u,string$role,string$id,array$input):array
    {
        $this->confirmed($input);$this->governorRole($o,$u,$role);$status=$this->choice($input['status']??null,['in_progress','fulfilled','refused'],'popia_request_status_invalid');$reason=$this->text($input['reason']??null,1000,'popia_request_reason_required');$response=$this->nullableText($input['responseSummary']??null,2000,'popia_response_summary_invalid');if(in_array($status,['fulfilled','refused'],true)&&$response===null)throw new TrustException('popia_response_summary_required');$row=$this->scoped('popia_data_subject_requests',$o,$id,'popia_request_not_found');if(in_array($row['status'],['fulfilled','refused'],true))throw new TrustException('popia_request_immutable');$this->pdo->prepare("UPDATE popia_data_subject_requests SET status=:status,response_summary=:response,decided_by=UNHEX(:u),decision_reason=:reason,completed_at=CASE WHEN :terminal IN ('fulfilled','refused') THEN UTC_TIMESTAMP(6) ELSE NULL END WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)")->execute(['status'=>$status,'response'=>$response,'u'=>$u,'reason'=>$reason,'terminal'=>$status,'id'=>$id,'o'=>$o]);$payload=['dataSubjectRequestId'=>$id,'status'=>$status,'reason'=>$reason];$this->record($o,$row['project_id'],$u,'popia_data_subject_request','Data-subject request '.$status,$status,$payload,[$id]);$this->audit($o,$u,'popia.data_subject_request_transitioned','popia_data_subject_request',$id,$payload);return$this->one('popia_data_subject_requests',$o,$row['project_id'],$id,[]);
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function reportBreach(string$o,string$u,string$p,array$input):array
    {
        $this->assertProject($o,$u,$p);$this->confirmed($input);$detected=$this->dateTime($input['detectedAt']??null,'popia_breach_detected_invalid');$summary=$this->text($input['summary']??null,1000,'popia_breach_summary_required');$categories=$this->strings($input['dataCategories']??null,30,'popia_data_categories_invalid');$affected=$this->integer($input['subjectsAffected']??null,0,100000000,'popia_subject_count_invalid');$rating=$this->choice($input['riskRating']??null,['low','medium','high','critical'],'popia_breach_risk_invalid');$notify=$input['regulatorNotificationRequired']??null;if(!is_bool($notify))throw new TrustException('popia_notification_assessment_required');$id=Identifier::generate();return$this->transaction(function()use($o,$u,$p,$detected,$summary,$categories,$affected,$rating,$notify,$id):array{$this->pdo->prepare("INSERT INTO popia_breaches(id,organisation_id,project_id,detected_at,summary,data_categories,subjects_affected,risk_rating,regulator_notification_required,status,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:detected,:summary,:categories,:affected,:rating,:notify,'open',UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'p'=>$p,'detected'=>$detected,'summary'=>$summary,'categories'=>$this->json($categories),'affected'=>$affected,'rating'=>$rating,'notify'=>$notify?1:0,'u'=>$u]);$payload=['breachId'=>$id,'riskRating'=>$rating,'subjectsAffected'=>$affected,'regulatorNotificationRequired'=>$notify,'regulatorNotificationSent'=>false];$this->record($o,$p,$u,'popia_breach','POPIA breach report','open',$payload,[$id]);$this->inbox($o,$p,'popia.breach_response_required','POPIA breach response required','Contain, assess and document this incident; no regulator notification is sent by Architex.',$rating,$payload);$this->audit($o,$u,'popia.breach_reported','popia_breach',$id,$payload);$this->risk($o,$p,'popia_breach',$id,'POPIA breach requires response',$summary,$rating,true);return$this->one('popia_breaches',$o,$p,$id,['data_categories']);});
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function transitionBreach(string$o,string$u,string$role,string$id,array$input):array
    {
        $this->confirmed($input);$this->governorRole($o,$u,$role);$status=$this->choice($input['status']??null,['contained','closed'],'popia_breach_status_invalid');$reason=$this->text($input['reason']??null,2000,'popia_breach_reason_required');$row=$this->scoped('popia_breaches',$o,$id,'popia_breach_not_found');$allowed=['open'=>['contained','closed'],'contained'=>['closed']];if(!in_array($status,$allowed[$row['status']]??[],true))throw new TrustException('popia_breach_transition_invalid');$notified=$this->nullableDateTime($input['regulatorNotifiedAt']??null,'popia_regulator_notification_invalid');if($status==='closed'&&(bool)$row['regulator_notification_required']&&$notified===null)throw new TrustException('popia_regulator_notification_evidence_required');$this->pdo->prepare('UPDATE popia_breaches SET status=:status,response_reason=:reason,managed_by=UNHEX(:u),regulator_notified_at=:notified WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)')->execute(['status'=>$status,'reason'=>$reason,'u'=>$u,'notified'=>$notified,'id'=>$id,'o'=>$o]);$payload=['breachId'=>$id,'status'=>$status,'reason'=>$reason,'regulatorNotificationSent'=>$notified!==null,'regulatorNotifiedAt'=>$notified];$this->record($o,$row['project_id'],$u,'popia_breach','POPIA breach '.$status,$status,$payload,[$id]);$this->audit($o,$u,'popia.breach_transitioned','popia_breach',$id,$payload);return$this->one('popia_breaches',$o,$row['project_id'],$id,['data_categories']);
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function resolveRisk(string$o,string$u,string$role,string$id,array$input):array
    {
        $this->confirmed($input);$this->governorRole($o,$u,$role);$reason=$this->text($input['reason']??null,1000,'trust_risk_resolution_required');$row=$this->scoped('trust_compliance_risks',$o,$id,'trust_risk_not_found');if($row['status']!=='open')throw new TrustException('trust_risk_immutable');$evidence=$this->nullableId($input['resolutionEvidenceItemId']??null,'trust_resolution_evidence_invalid');$links=[$id];if($row['source_type']==='trust_compliance_item'){$source=$this->scopedItem($o,$row['source_object_id']);if($evidence===null||$evidence===$row['source_object_id'])throw new TrustException('trust_replacement_evidence_required');$replacement=$this->scopedItem($o,$evidence);$replacementStatus=$this->effectiveStatus($replacement['expires_on'],isset($replacement['coverage_amount_cents'])?(int)$replacement['coverage_amount_cents']:null,isset($replacement['required_coverage_cents'])?(int)$replacement['required_coverage_cents']:null,(string)$replacement['grade']);if($replacement['project_id']!==$row['project_id']||$replacement['subject_name']!==$source['subject_name']||$replacement['category']!==$source['category']||!in_array($replacementStatus,['current','expiring'],true))throw new TrustException('trust_replacement_evidence_invalid');$links[]=$evidence;}elseif($row['source_type']==='popia_breach'){$breach=$this->scoped('popia_breaches',$o,$row['source_object_id'],'popia_breach_not_found');if($breach['status']!=='closed')throw new TrustException('trust_source_workflow_open');}else{throw new TrustException('trust_source_workflow_open');}$this->pdo->prepare("UPDATE trust_compliance_risks SET status='resolved',resolved_by=UNHEX(:u),resolution_reason=:reason,resolved_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)")->execute(['u'=>$u,'reason'=>$reason,'id'=>$id,'o'=>$o]);$this->pdo->prepare("UPDATE trust_agent_recommendations SET status='resolved' WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND source_type=:type AND source_object_id=UNHEX(:source) AND status='open'")->execute(['o'=>$o,'p'=>$row['project_id'],'type'=>$row['source_type'],'source'=>$row['source_object_id']]);$payload=['riskId'=>$id,'reason'=>$reason,'sourceType'=>$row['source_type'],'resolutionEvidenceItemId'=>$evidence];$this->record($o,$row['project_id'],$u,'trust_compliance_risk','Compliance risk resolved','resolved',$payload,$links);$this->audit($o,$u,'trust.compliance_risk_resolved','trust_compliance_risk',$id,$payload);return$this->one('trust_compliance_risks',$o,$row['project_id'],$id,[]);
    }

    /** @return array<string,mixed> */
    public function workspace(string$o,string$u,string$p):array
    {
        $this->assertProject($o,$u,$p);$items=$this->all('trust_compliance_items',$o,$p,['details']);foreach($items as&$item)$item['status']=$this->effectiveStatus($item['expiresOn']??null,$item['coverageAmountCents']??null,$item['requiredCoverageCents']??null,(string)$item['grade']);unset($item);$activities=$this->all('popia_processing_activities',$o,$p,['data_subjects','data_categories','recipients']);$today=(new DateTimeImmutable('today'))->format('Y-m-d');foreach($activities as&$activity)if($activity['status']==='active'&&$activity['retentionUntil']<$today)$activity['status']='review_due';unset($activity);return['complianceItems'=>$items,'processingActivities'=>$activities,'dataSubjectRequests'=>$this->all('popia_data_subject_requests',$o,$p,[]),'breaches'=>$this->all('popia_breaches',$o,$p,['data_categories']),'risks'=>$this->all('trust_compliance_risks',$o,$p,[]),'recommendations'=>$this->all('trust_agent_recommendations',$o,$p,[]),'boundaries'=>['externalChecksSimulated'=>false,'externalVerificationRequiresProviderEvidence'=>true,'regulatorNotificationSent'=>false,'complianceBadgeIsApproval'=>false]];
    }

    private function assertDocumentType(string$category,string$type,string$authority):void{if($category==='professional_registration'&&(!in_array(strtoupper($authority),self::PROFESSIONAL_BODIES,true)||$type!=='registration_certificate'))throw new TrustException('trust_professional_body_invalid');if($category==='company_document'&&!in_array($type,self::COMPANY_DOCUMENTS,true))throw new TrustException('trust_company_document_invalid');if($category==='insurance'&&!in_array($type,self::INSURANCE_DOCUMENTS,true))throw new TrustException('trust_insurance_document_invalid');if($category==='contractor_supplier'&&!in_array($type,self::CONTRACTOR_DOCUMENTS,true))throw new TrustException('trust_contractor_document_invalid');}
    private function assertSubjectCategory(string$subjectType,string$category):void{if($category==='professional_registration'&&$subjectType!=='professional')throw new TrustException('trust_subject_category_invalid');if($category==='company_document'&&$subjectType!=='company')throw new TrustException('trust_subject_category_invalid');if($category==='insurance'&&!in_array($subjectType,['professional','company'],true))throw new TrustException('trust_subject_category_invalid');if($category==='contractor_supplier'&&!in_array($subjectType,['contractor','supplier'],true))throw new TrustException('trust_subject_category_invalid');}
    private function effectiveStatus(?string$expires,?int$coverage,?int$required,string$grade):string{if($grade==='rejected')return'rejected';$today=(new DateTimeImmutable('today'))->format('Y-m-d');if($expires!==null&&$expires<$today)return'expired';if($coverage!==null&&$required!==null&&$coverage<$required)return'coverage_gap';$soon=(new DateTimeImmutable('today +60 days'))->format('Y-m-d');return$expires!==null&&$expires<=$soon?'expiring':'current';}
    private function risk(string$o,string$p,string$type,string$source,string$title,string$reason,string$severity,bool$blocks):void{$id=Identifier::generate();$this->pdo->prepare("INSERT INTO trust_compliance_risks(id,organisation_id,project_id,source_type,source_object_id,title,reason,severity,blocks_appointment,status) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:type,UNHEX(:source),:title,:reason,:severity,:blocks,'open')")->execute(['id'=>$id,'o'=>$o,'p'=>$p,'type'=>$type,'source'=>$source,'title'=>$title,'reason'=>$reason,'severity'=>$severity,'blocks'=>$blocks?1:0]);$this->inbox($o,$p,'trust.compliance_risk','Trust/compliance risk requires review',$reason,$severity,['riskId'=>$id,'sourceType'=>$type,'sourceObjectId'=>$source,'blocksAppointment'=>$blocks]);$this->pdo->prepare("INSERT INTO trust_agent_recommendations(id,organisation_id,project_id,source_type,source_object_id,title,rationale,severity,status) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:type,UNHEX(:source),:title,:reason,:severity,'open')")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'type'=>$type,'source'=>$source,'title'=>$title,'reason'=>$reason,'severity'=>$severity]);}
    /** @param array<string,mixed>$payload @param list<string>$links */ private function record(string$o,string$p,string$u,string$type,string$title,string$status,array$payload,array$links):void{$normal=match($status){'current','fulfilled','contained','closed'=>'approved','rejected','refused'=>'rejected',default=>'pending_review'};$phase=$this->projectPhase($o,$p);$this->pdo->prepare("INSERT INTO project_records(id,organisation_id,project_id,phase,module_key,record_type,title,status,payload,approvals,linked_record_ids,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:phase,:module,:type,:title,:status,:payload,'{\"required\":true,\"humanReviewRequired\":true}',:links,UNHEX(:u))")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'phase'=>$phase,'module'=>self::MODULE,'type'=>$type,'title'=>substr($title,0,220),'status'=>$normal,'payload'=>$this->json(['workflowStatus'=>$status]+$payload),'links'=>$this->json($links),'u'=>$u]);}
    /** @param array<string,mixed>$payload */ private function inbox(string$o,string$p,string$type,string$title,string$detail,string$priority,array$payload):void{$this->pdo->prepare("INSERT INTO inbox_items(id,organisation_id,project_id,assigned_role,event_type,title,detail,priority,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),'owner',:type,:title,:detail,:priority,:payload)")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'type'=>$type,'title'=>substr($title,0,220),'detail'=>substr($detail,0,1000),'priority'=>$priority,'payload'=>$this->json($payload)]);}
    /** @param array<string,mixed>$metadata */ private function audit(string$o,string$u,string$action,string$type,string$id,array$metadata):void{(new AuditService($this->pdo))->append($o,$u,$action,$type,$id,$metadata);}
    private function projectPhase(string$o,string$p):string{$s=$this->pdo->prepare('SELECT current_phase FROM projects WHERE organisation_id=UNHEX(:o) AND id=UNHEX(:p)');$s->execute(['o'=>$o,'p'=>$p]);$phase=$s->fetchColumn();return is_string($phase)?$phase:'onboarding';}
    /** @return array<string,mixed> */ private function item(string$o,string$p,string$id):array{return$this->one('trust_compliance_items',$o,$p,$id,['details']);}
    /** @return array<string,mixed> */ private function one(string$table,string$o,string$p,string$id,array$json):array{$s=$this->pdo->prepare("SELECT *,LOWER(HEX(id)) id FROM $table WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND id=UNHEX(:id)");$s->execute(['o'=>$o,'p'=>$p,'id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new TrustException('trust_record_not_found');foreach($json as$c)$r[$c]=$this->decode($r[$c]);return$this->camel($r);}
    /** @return list<array<string,mixed>> */ private function all(string$table,string$o,string$p,array$json):array{$s=$this->pdo->prepare("SELECT *,LOWER(HEX(id)) id FROM $table WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at,id");$s->execute(['o'=>$o,'p'=>$p]);$out=[];foreach($s->fetchAll()as$r){foreach($json as$c)$r[$c]=$this->decode($r[$c]);$out[]=$this->camel($r);}return$out;}
    /** @return array<string,mixed> */ private function scopedItem(string$o,string$id):array{$s=$this->pdo->prepare('SELECT *,LOWER(HEX(project_id)) project_id,LOWER(HEX(created_by)) created_by FROM trust_compliance_items WHERE organisation_id=UNHEX(:o) AND id=UNHEX(:id)');$s->execute(['o'=>$o,'id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new TrustException('trust_compliance_item_not_found');return$r;}
    /** @return array<string,mixed> */ private function scoped(string$table,string$o,string$id,string$error):array{$s=$this->pdo->prepare("SELECT *,LOWER(HEX(project_id)) project_id FROM $table WHERE organisation_id=UNHEX(:o) AND id=UNHEX(:id)");$s->execute(['o'=>$o,'id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new TrustException($error);foreach($r as$key=>$value)if(is_string($key)&&str_ends_with($key,'_id')&&is_string($value)&&strlen($value)===16)$r[$key]=bin2hex($value);return$r;}
    private function assertProject(string$o,string$u,string$p):void{$s=$this->pdo->prepare("SELECT 1 FROM projects p JOIN organisation_memberships m ON m.organisation_id=p.organisation_id AND m.user_id=UNHEX(:u) AND m.status='active' WHERE p.organisation_id=UNHEX(:o) AND p.id=UNHEX(:p)");$s->execute(['o'=>$o,'u'=>$u,'p'=>$p]);if($s->fetchColumn()===false)throw new TrustException('trust_project_not_found');}
    private function assertMember(string$o,string$u):void{$s=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$o,'u'=>$u]);if($s->fetchColumn()===false)throw new TrustException('membership_not_found');}
    private function governor(string$o,string$u):void{$s=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active' AND role IN ('owner','admin')");$s->execute(['o'=>$o,'u'=>$u]);if($s->fetchColumn()===false)throw new TrustException('trust_review_permission_denied');}
    private function governorRole(string$o,string$u,string$role):void{$this->governor($o,$u);if(!in_array($role,['owner','admin'],true))throw new TrustException('trust_review_permission_denied');}
    private function assertEvidence(string$o,string$p,string$id):void{$s=$this->pdo->prepare("SELECT 1 FROM stored_files WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND id=UNHEX(:id) AND status='active'");$s->execute(['o'=>$o,'p'=>$p,'id'=>$id]);if($s->fetchColumn()===false)throw new TrustException('trust_evidence_not_found');}
    /** @return array<string,mixed> */ private function camel(array$r):array{$out=[];foreach($r as$key=>$v){if(in_array($key,['organisation_id','project_id'],true))continue;$name=preg_replace_callback('/_([a-z])/',static fn($m)=>strtoupper($m[1]),(string)$key);if(is_string($v)&&strlen($v)===16&&($key==='id'||str_ends_with((string)$key,'_id')||str_ends_with((string)$key,'_by')))$v=bin2hex($v);if(in_array($key,['regulator_notification_required','blocks_appointment'],true))$v=(bool)$v;if(in_array($key,['coverage_amount_cents','required_coverage_cents','subjects_affected'],true)&&$v!==null)$v=(int)$v;$out[$name]=$v;}return$out;}
    /** @template T @param callable():T$f @return T */ private function transaction(callable$f):mixed{$this->pdo->beginTransaction();try{$v=$f();$this->pdo->commit();return$v;}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
    /** @param array<string,mixed>$input */ private function confirmed(array$input):void{if(($input['humanConfirmed']??false)!==true)throw new TrustException('trust_human_confirmation_required');}
    private function text(mixed$v,int$max,string$error):string{if(!is_string($v)||trim($v)===''||mb_strlen(trim($v))>$max)throw new TrustException($error);return trim($v);}
    private function nullableText(mixed$v,int$max,string$error):?string{if($v===null||$v==='')return null;return$this->text($v,$max,$error);}
    /** @param list<string>$choices */ private function choice(mixed$v,array$choices,string$error):string{if(!is_string($v)||!in_array($v,$choices,true))throw new TrustException($error);return$v;}
    private function id(mixed$v,string$error):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new TrustException($error);return strtolower($v);}
    private function nullableId(mixed$v,string$error):?string{return$v===null||$v===''?null:$this->id($v,$error);}
    private function integer(mixed$v,int$min,int$max,string$error):int{if(!is_int($v)&&!(is_string($v)&&preg_match('/\A\d+\z/',$v)===1))throw new TrustException($error);$n=(int)$v;if($n<$min||$n>$max)throw new TrustException($error);return$n;}
    private function nullableInteger(mixed$v,string$error):?int{return$v===null||$v===''?null:$this->integer($v,0,PHP_INT_MAX,$error);}
    private function date(mixed$v,string$error):string{if(!is_string($v)||DateTimeImmutable::createFromFormat('!Y-m-d',$v)?->format('Y-m-d')!==$v)throw new TrustException($error);return$v;}
    private function nullableDate(mixed$v,string$error):?string{return$v===null||$v===''?null:$this->date($v,$error);}
    private function dateTime(mixed$v,string$error):string{if(!is_string($v))throw new TrustException($error);try{$d=new DateTimeImmutable($v);}catch(Throwable){throw new TrustException($error);}return$d->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s.u');}
    /** @return list<string> */ private function strings(mixed$v,int$max,string$error):array{if(!is_array($v)||$v===[]||count($v)>$max)throw new TrustException($error);$out=[];foreach($v as$x){if(!is_string($x)||trim($x)===''||mb_strlen(trim($x))>160)throw new TrustException($error);$out[]=trim($x);}return array_values(array_unique($out));}
    /** @return array<string,mixed> */ private function object(mixed$v,string$error):array{if(!is_array($v)||($v!==[]&&array_is_list($v))||count($v)>100)throw new TrustException($error);return$v;}
    private function nullableDateTime(mixed$v,string$error):?string{return$v===null||$v===''?null:$this->dateTime($v,$error);}
    private function json(mixed$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES);}
    /** @return array<mixed> */ private function decode(mixed$v):array{if(!is_string($v))return[];$d=json_decode($v,true,512,JSON_THROW_ON_ERROR);return is_array($d)?$d:[];}
}
